[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$JsonPath,[string]$SchemaPath=(Join-Path $PSScriptRoot '..\references\es-resource-collection-perf-trend.v1.schema.json'))
$ErrorActionPreference='Stop';$errors=[Collections.Generic.List[string]]::new()
try{$j=Get-Content -LiteralPath (Resolve-Path $JsonPath) -Raw -Encoding UTF8|ConvertFrom-Json;if($j.trendId -ne 'es-resource-collection.perf-trend.v1'){[void]$errors.Add('invalid trendId')};$rows=@($j.reports);if($j.reportCount -ne $rows.Count){[void]$errors.Add('reportCount mismatch')};$keys=@($rows|ForEach-Object {"$($_.format)|$($_.fileCount)|$($_.report)"});$sorted=@($keys|Sort-Object);if((ConvertTo-Json $keys -Compress) -ne (ConvertTo-Json $sorted -Compress)){[void]$errors.Add('reports must be deterministically sorted')};foreach($r in $rows){if($r.fileCount -lt 0 -or $r.coldFilesPerSecond -lt 0 -or $r.incrementalFilesPerSecond -lt 0 -or $r.speedupRatio -lt 0 -or $r.failedCount -lt 0){[void]$errors.Add("invalid metrics: $($r.report)")}}}catch{[void]$errors.Add($_.Exception.Message)}
[ordered]@{validator='Test-ESResourceCollectionPerfTrend';path=$JsonPath;schemaPath=$SchemaPath;valid=($errors.Count -eq 0);errorCount=$errors.Count;errors=@($errors);runtimeStatus='runtime-not-run'}|ConvertTo-Json -Depth 8;if($errors.Count){exit 1}
